<script setup lang="ts">
import { message } from 'ant-design-vue';import { onMounted,reactive,ref } from 'vue';import AdminPageHeader from '@/components/admin/AdminPageHeader.vue';import { platformDashboardApi } from '@/services/platformFlowDashboard';import type { PlatformDashboard } from '@/types/platformFlowDashboard'
const items=ref<PlatformDashboard[]>([]),selected=ref<PlatformDashboard|null>(null),versions=ref<any[]>([]),error=ref(''),saving=ref(false);const form=reactive({code:'PLATFORM_HOME',name:'平台仪表盘',description:'',draft:'{"statistics":["AUTHORIZED_SYSTEMS","OPEN_TASKS","UNREAD_MESSAGES","FLOW_RUNS"],"quickEntries":["FLOW","WORK","TODO","MESSAGE","AGENT"],"includeHealth":true}'});async function load(){items.value=await platformDashboardApi.list();if(selected.value){selected.value=items.value.find(v=>v.id===selected.value?.id)||null;await loadVersions()}}function select(v:PlatformDashboard){selected.value=v;Object.assign(form,{code:v.code,name:v.name,description:v.description||'',draft:JSON.stringify(v.draft,null,2)});void loadVersions()}async function save(){saving.value=true;error.value='';try{const draft=JSON.parse(form.draft);const value=selected.value?await platformDashboardApi.save(selected.value.id,{name:form.name,description:form.description,draft,expectedVersion:selected.value.version}):await platformDashboardApi.create({code:form.code,name:form.name,description:form.description,draft});selected.value=value;message.success('草稿已保存');await load()}catch(e){error.value=e instanceof Error?e.message:'保存失败'}finally{saving.value=false}}async function check(){if(!selected.value)return;const result=await platformDashboardApi.check(selected.value.id);result.valid?message.success('校验通过'):message.error(result.issues.join('; '))}async function publish(){if(!selected.value)return;await platformDashboardApi.publish(selected.value.id,selected.value.version);message.success('已发布');await load()}async function loadVersions(){versions.value=selected.value?await platformDashboardApi.versions(selected.value.id):[]}async function restore(v:any){if(!selected.value)return;selected.value=await platformDashboardApi.restore(selected.value.id,v.versionNumber,selected.value.version);select(selected.value);message.success('版本已恢复为新草稿')}onMounted(()=>load().catch(e=>error.value=e.message))
</script><template><section class="admin-page"><AdminPageHeader title="平台仪表盘管理" description="草稿、校验、发布、版本与恢复均属于平台 scope。"><template #actions><a-button @click="selected=null">新建</a-button><a-button :loading="saving" type="primary" @click="save">保存草稿</a-button></template></AdminPageHeader><a-alert v-if="error" type="error" :message="error"/><div class="editor"><aside><button v-for="item in items" :key="item.id" @click="select(item)"><strong>{{ item.name }}</strong><small>{{ item.status }} · v{{ item.activeVersionNumber||'-' }}</small></button></aside><main><a-form layout="vertical"><a-form-item label="代码"><a-input v-model:value="form.code" :disabled="!!selected"/></a-form-item><a-form-item label="名称"><a-input v-model:value="form.name"/></a-form-item><a-form-item label="说明"><a-input v-model:value="form.description"/></a-form-item><a-form-item label="配置 JSON"><a-textarea v-model:value="form.draft" :rows="12"/></a-form-item><a-space><a-button :disabled="!selected" @click="check">校验</a-button><a-button :disabled="!selected" type="primary" @click="publish">发布</a-button></a-space></a-form><section v-if="versions.length"><h3>版本</h3><a-space wrap><a-button v-for="v in versions" :key="v.id" size="small" @click="restore(v)">v{{ v.versionNumber }} 恢复为草稿</a-button></a-space></section></main></div></section></template><style scoped>.admin-page{display:grid;gap:16px}.editor{display:grid;grid-template-columns:240px 1fr;gap:16px}.editor aside{display:grid;align-content:start;gap:7px}.editor aside button{display:grid;gap:4px;text-align:left;padding:11px;border:1px solid #dce3e8;border-radius:6px;background:#fff}.editor main{padding:18px;border:1px solid #dce3e8;border-radius:8px;background:#fff}@media(max-width:760px){.editor{grid-template-columns:1fr}}</style>
